(function(){
  'use strict';
  var body=document.body;
  if(!body || !body.classList.contains('fqx-v145-restaurant-admin')) return;

  function qs(s,ctx){return (ctx||document).querySelector(s)}
  function qsa(s,ctx){return Array.prototype.slice.call((ctx||document).querySelectorAll(s))}

  // Mobile sidebar drawer - UI only.
  document.addEventListener('click', function(e){
    var toggle=e.target.closest('.mq-sidebar-toggle');
    if(toggle){ e.preventDefault(); body.classList.toggle('fqx-sidebar-open'); }
    if(e.target.closest('.mq-sidebar-overlay') || e.target.closest('.nav-item')){ body.classList.remove('fqx-sidebar-open'); }
  });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') body.classList.remove('fqx-sidebar-open'); });

  // Add data labels for mobile card table layout.
  qsa('table.data-table').forEach(function(table){
    var heads=qsa('thead th', table).map(function(th){return th.textContent.trim();});
    qsa('tbody tr', table).forEach(function(tr){
      qsa('td', tr).forEach(function(td,i){ if(!td.getAttribute('data-label')) td.setAttribute('data-label', heads[i] || ''); });
    });
  });

  // Room template selected highlight and text sync.
  document.addEventListener('change', function(e){
    var radio=e.target.closest('.fqx-v141-template-radio');
    if(radio){
      var picker=radio.closest('.fqx-v134-template-picker');
      if(picker){
        qsa('.fqx-v141-template-option', picker).forEach(function(opt){
          var is=!!qs('input[type="radio"]:checked', opt);
          opt.classList.toggle('is-selected', is);
          var badge=qs('.fqx-v141-template-top b', opt);
          var cta=qs('.fqx-v141-template-cta', opt);
          if(badge) badge.textContent=is?'Selected ✓':'Select Template';
          if(cta) cta.textContent=is?'Selected ✓':'Tap to Select';
          if(is){
            var name=(qs('.fqx-v141-template-name', opt)||{}).textContent || '';
            qsa('.fqx-v144-current-template,.fqx-v144-selected-template-name', picker).forEach(function(n){n.textContent=name.trim();});
          }
        });
      }
    }
    var select=e.target.closest('.fqx-v142-template-select');
    if(select){
      var studio=select.closest('.fqx-v142-room-template-studio');
      var current=studio && qs('.fqx-v142-current-name', studio);
      if(current){ current.textContent = select.options[select.selectedIndex] ? select.options[select.selectedIndex].textContent.trim() : ''; }
    }
  });

  // Bill Branding page: wrap form and inject lightweight live preview without touching backend fields/actions.
  function initBillBrandingPreview(){
    var title=qsa('.section-title').filter(function(el){ return /Bill Branding|Receipt Settings/i.test(el.textContent||''); })[0];
    if(!title) return;
    var card=title.closest('.section-card');
    if(!card || card.classList.contains('fqx-v145-bill-ready')) return;
    var form=qs('form', card); if(!form) return;
    card.classList.add('fqx-v145-bill-ready');
    var shell=document.createElement('div'); shell.className='fqx-v145-settings-layout';
    var holder=document.createElement('div'); holder.className='fqx-v145-settings-form';
    form.parentNode.insertBefore(shell, form);
    shell.appendChild(holder); holder.appendChild(form);
    var preview=document.createElement('aside'); preview.className='fqx-v145-bill-preview';
    preview.innerHTML='<h3>Live Bill Preview</h3><p class="text-muted">Professional bill/receipt branding preview.</p><div class="fqx-v145-receipt"><div class="fqx-v145-receipt-logo"></div><h4 class="fqx-r-name"></h4><div class="muted fqx-r-tag"></div><div class="muted fqx-r-contact"></div><div class="fqx-v145-receipt-row"><b>Bill No.</b><span>#INV-000124</span></div><div class="fqx-v145-receipt-row"><b>Date</b><span>18 May 2025, 04:35 PM</span></div><div class="fqx-v145-receipt-row"><span>Paneer Tikka × 1</span><span>₹180.00</span></div><div class="fqx-v145-receipt-row"><span>Veg Biryani × 1</span><span>₹220.00</span></div><div class="fqx-v145-receipt-row"><span>Butter Naan × 2</span><span>₹80.00</span></div><div class="fqx-v145-receipt-row"><span>GST/Tax</span><span>₹30.00</span></div><div class="fqx-v145-receipt-total"><span>Total</span><span>₹630.00</span></div><div class="fqx-v145-receipt-note"></div></div>';
    shell.appendChild(preview);
    var logoBox=qs('.fqx-v145-receipt-logo', preview);
    var existingLogo=qs('.menuqr-brand-logo img,.menuqr-brand-logo-lg img,img[src*="fluuexqr-logo"]', form);
    if(existingLogo){ var img=existingLogo.cloneNode(true); img.removeAttribute('style'); logoBox.appendChild(img); }
    else { logoBox.textContent='FluuexQR'; logoBox.style.color='#ea580c'; logoBox.style.fontWeight='900'; logoBox.style.fontSize='28px'; }
    var name=qs('.fqx-r-name', preview), tag=qs('.fqx-r-tag', preview), contact=qs('.fqx-r-contact', preview), note=qs('.fqx-v145-receipt-note', preview);
    function val(n){ var el=qs('[name="'+n+'"]', form); return el ? el.value.trim() : ''; }
    function disabledRestaurantName(){
      var labels=qsa('.form-group', form).filter(function(g){return /Restaurant Name/i.test(g.textContent||'');})[0];
      var input=labels&&qs('input',labels); return input ? input.value.trim() : '';
    }
    function sync(){
      name.textContent=disabledRestaurantName() || val('restaurant_name') || 'Restaurant Name';
      tag.textContent=val('tagline') || 'Hotel & Restaurant Automation';
      contact.textContent=[val('phone'),val('email'),val('address')].filter(Boolean).join(' · ');
      note.textContent=val('thank_you_text') || val('footer_text') || 'Thank you for dining with us!';
    }
    form.addEventListener('input', sync); sync();
  }

  // Reviews page: add management feel when only Google review settings exist.
  function initReviewsUi(){
    var title=qsa('.section-title,.chart-title').filter(function(el){ return /Review/i.test(el.textContent||''); })[0];
    if(!title) return;
    var page=title.closest('.page-body'); if(!page || page.classList.contains('fqx-v145-reviews-ready')) return;
    if(!/tab=reviews/.test(location.search)) return;
    page.classList.add('fqx-v145-reviews-ready');
    var stats=document.createElement('div');
    stats.className='fqx-v145-review-boost';
    stats.innerHTML='<div class="fqx-v145-review-card"><div class="card-title">Average Rating</div><div class="card-value">4.8 ★</div><div class="card-sub">Google review ready</div></div><div class="fqx-v145-review-card"><div class="card-title">Review Visibility</div><div class="card-value">Active</div><div class="card-sub">Menu, bill and tracking prompts</div></div><div class="fqx-v145-review-card"><div class="card-title">Customer Feedback</div><div class="fqx-v145-stars">★★★★★</div><div class="card-sub">Connect review link to start collecting reviews.</div></div>';
    var firstCard=qs('.section-card', page); if(firstCard) firstCard.parentNode.insertBefore(stats, firstCard.nextSibling);
    var list=document.createElement('div');
    list.className='section-card fqx-v145-empty-panel';
    list.innerHTML='<h3>Review Management</h3><p>No direct review records found in the current backend table. Existing Google review link/click tracking flow is kept unchanged. Once reviews are stored in the backend, this area can show customer review list, reply buttons and status badges.</p>';
    page.appendChild(list);
  }

  initBillBrandingPreview();
  initReviewsUi();
})();

/* v153 Rooms & QR UI interactions */
(function(){
  'use strict';
  function qsa(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s));}
  function qs(s,c){return (c||document).querySelector(s);}
  document.addEventListener('click', function(e){
    var parent=e.target.closest('.fq-room-parent');
    if(parent && window.innerWidth <= 1024){
      var group=parent.closest('.fq-room-nav-group');
      if(group && group.classList.contains('is-open')){ return; }
      if(group){ e.preventDefault(); group.classList.toggle('is-open'); }
    }
    var printBtn=e.target.closest('.fq-print-card-btn');
    if(printBtn){
      e.preventDefault();
      window.print();
    }
  });
  document.addEventListener('change', function(e){
    var templateRadio=e.target.closest('.fq-template-radio');
    if(templateRadio){
      var grid=templateRadio.closest('.fq-template-grid');
      if(grid){
        qsa('.fq-template-card', grid).forEach(function(card){
          var checked=!!qs('.fq-template-radio:checked', card);
          card.classList.toggle('fq-template-selected', checked);
          var badge=qs('.fq-template-badge', card);
          if(badge){ badge.textContent = checked ? 'Selected ✓' : 'Select'; }
        });
      }
    }
    var roomSelect=e.target.closest('.fq-room-template-room-select');
    if(roomSelect){
      var form=qs('.fq-template-save-form');
      var hidden=form && qs('.fq-template-room-id', form);
      if(hidden){ hidden.value=roomSelect.value; }
      var url=new URL(window.location.href);
      url.searchParams.set('tab','rooms');
      url.searchParams.set('section','templates');
      url.searchParams.set('room_id',roomSelect.value);
      window.location.href=url.toString();
    }
  });
})();


// v154 WiFi QR UI interactions: password eye, security card sync, live preview, alert close.
(function(){
  'use strict';
  var page=document.querySelector('.fq-wifi-qr-page');
  if(!page) return;
  page.addEventListener('click', function(e){
    var close=e.target.closest('.fq-alert-close');
    if(close){ var alert=close.closest('.fq-wifi-alert'); if(alert) alert.remove(); return; }
    var eye=e.target.closest('.fq-password-toggle');
    if(eye){ var input=eye.closest('.fq-field-icon').querySelector('input'); if(input){ input.type=input.type==='password'?'text':'password'; eye.textContent=input.type==='password'?'◌':'◉'; } return; }
    var option=e.target.closest('.fq-security-option');
    if(option){
      var value=(option.querySelector('input')||{}).getAttribute('data-security-value');
      var select=page.querySelector('.fq-security-select');
      if(select && value){ select.value=value; select.dispatchEvent(new Event('change',{bubbles:true})); }
      page.querySelectorAll('.fq-security-option').forEach(function(o){o.classList.remove('is-selected'); var inp=o.querySelector('input'); if(inp) inp.checked=false;});
      option.classList.add('is-selected'); var input=option.querySelector('input'); if(input) input.checked=true;
    }
  });
  page.addEventListener('input', function(e){
    var ssid=page.querySelector('.fq-live-ssid');
    var pass=page.querySelector('.fq-live-password');
    var ssidPreview=page.querySelector('.fq-preview-ssid');
    var passPreview=page.querySelector('.fq-preview-password');
    if(ssid && ssidPreview){ ssidPreview.textContent=ssid.value.trim() || 'FluuexQR_Hotel'; }
    if(pass && passPreview){ passPreview.textContent=pass.value.trim() || 'FluuexQR@2025'; }
  });
  page.addEventListener('change', function(e){
    var select=e.target.closest('.fq-security-select');
    if(select){
      page.querySelectorAll('.fq-security-option').forEach(function(o){
        var inp=o.querySelector('input');
        var is=inp && inp.getAttribute('data-security-value')===select.value;
        o.classList.toggle('is-selected', !!is);
        if(inp) inp.checked=!!is;
      });
    }
  });
})();


// v156 bills preview row sync + better mobile handling.
document.addEventListener('DOMContentLoaded', function(){
  var page=document.querySelector('.fq-bills-page-v156');
  if(!page) return;
  var rows=page.querySelectorAll('.fq-bills-table tbody tr');
  var preview=page.querySelector('.fq-sample-bill-preview .fq-mini-invoice');
  rows.forEach(function(row){
    row.addEventListener('click', function(e){
      if(e.target.closest('a,button,select,input,form')) return;
      rows.forEach(function(r){ r.classList.remove('is-selected-bill'); });
      row.classList.add('is-selected-bill');
    });
  });
});


// v158 Bill Branding UI interactions
(function(){
  document.addEventListener('DOMContentLoaded', function(){
    var page=document.querySelector('.fq-bill-branding-page'); if(!page) return;
    var note=page.querySelector('textarea[name="thank_you_text"]'); var counter=page.querySelector('.fq-bb-count');
    function updCount(){ if(note&&counter){ counter.textContent=(note.value||'').length + '/120'; }} updCount(); if(note){ note.addEventListener('input', updCount); }
    var root=page; var color=page.querySelector('input[name="bill_brand_color"]'); var colorText=page.querySelector('[data-fq-color-text]');
    function setColor(v){ if(!v) return; page.style.setProperty('--fq-bill-accent', v); if(color) color.value=v; if(colorText) colorText.value=v; }
    if(color){ color.addEventListener('input', function(){ setColor(color.value); }); }
    if(colorText){ colorText.addEventListener('input', function(){ setColor(colorText.value); }); }
    page.querySelectorAll('[data-fq-color]').forEach(function(btn){ btn.addEventListener('click', function(){ setColor(btn.getAttribute('data-fq-color')); }); });
    var previewAll=page.querySelector('[data-fq-preview-all]'); if(previewAll){ previewAll.addEventListener('click', function(){ page.querySelectorAll('.fq-bb-preview-card').forEach(function(c){ c.animate([{transform:'scale(1)'},{transform:'scale(1.015)'},{transform:'scale(1)'}],{duration:350}); }); }); }
    var test=page.querySelector('[data-fq-test-print]'); if(test){ test.addEventListener('click', function(){ window.print(); }); }
  });
})();


// v160 Bill Branding: make all UI controls functional without changing backend actions.
(function(){
  function qs(s,c){return (c||document).querySelector(s)}
  function qsa(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}
  function setPreviewHTML(box, html){ if(box){ box.innerHTML=html; box.classList.toggle('is-empty', !html); } }
  function printElement(el, title){
    if(!el) return window.print();
    var w=window.open('', 'fq_bill_print', 'width=520,height=780');
    if(!w){ window.print(); return; }
    w.document.write('<!doctype html><html><head><title>'+ (title||'Print') +'</title><style>body{margin:0;padding:18px;background:#fff;color:#000;font-family:Arial,sans-serif}.fq-a4-preview{max-width:760px;margin:auto}.fq-thermal-paper{width:300px;margin:auto}.fq-round-badge{margin:auto}img{max-width:100%;height:auto}table{width:100%;border-collapse:collapse}td,th{padding:4px;border-bottom:1px solid #ddd}.fq-bb-btn,.no-print{display:none!important}</style></head><body>'+el.outerHTML+'</body></html>');
    w.document.close(); w.focus(); setTimeout(function(){w.print();},350);
  }
  document.addEventListener('DOMContentLoaded', function(){
    var page=qs('.fq-bill-branding-page'); if(!page) return;
    var form=qs('#fqBillBrandingForm');
    var save=qs('.fq-bb-btn-primary', page);
    if(form && save){ form.addEventListener('submit', function(){ save.classList.add('is-saving'); save.innerHTML='Saving...'; }); }
    qsa('[data-fq-logo-file]', page).forEach(function(input){
      input.addEventListener('change', function(){
        var key=input.getAttribute('data-fq-logo-file');
        var file=input.files && input.files[0]; if(!file) return;
        var url=URL.createObjectURL(file);
        var img='<img src="'+url+'" alt="Logo preview">';
        setPreviewHTML(qs('[data-fq-logo-preview="'+key+'"]', page), img + (key==='header' ? '<button type="button" class="fq-icon-btn" data-fq-remove-logo="header">✕</button>' : ''));
        var a4=qs('.fq-invoice-head img', page); if(a4) a4.src=url;
      });
    });
    page.addEventListener('click', function(e){
      var rm=e.target.closest('[data-fq-remove-logo]');
      if(rm){
        e.preventDefault();
        var key=rm.getAttribute('data-fq-remove-logo');
        var hidden=qs('[data-fq-logo-hidden="'+key+'"]', page); if(hidden) hidden.value='';
        setPreviewHTML(qs('[data-fq-logo-preview="'+key+'"]', page), '<strong>No logo selected</strong>');
      }
      var preview=e.target.closest('[data-fq-preview-all]');
      if(preview){
        e.preventDefault();
        qsa('.fq-a4-preview,.fq-thermal-paper,.fq-round-badge', page).forEach(function(el){el.classList.remove('is-pulse'); void el.offsetWidth; el.classList.add('is-pulse');});
        var first=qs('.fq-live-bill-preview', page); if(first) first.scrollIntoView({behavior:'smooth',block:'center'});
      }
      var test=e.target.closest('[data-fq-test-print]');
      if(test){ e.preventDefault(); printElement(qs('.fq-thermal-paper', page), 'Thermal Bill Preview'); }
      var badge=e.target.closest('[data-fq-customize-badge]');
      if(badge){
        e.preventDefault();
        var txt=window.prompt('Badge text', (qs('.fq-round-badge span', page)||{}).innerText || 'Thank you!\nVisit again.');
        if(txt!==null){ var s=qs('.fq-round-badge span', page); if(s) s.innerHTML=txt.replace(/\n/g,'<br>'); }
      }
      var disabled=e.target.closest('a.is-disabled'); if(disabled){ e.preventDefault(); alert('No bill found yet. Create an order/bill first, then this action will work.'); }
    });
    qsa('.fq-paper-card input[type="radio"]', page).forEach(function(r){
      function sync(){ qsa('.fq-paper-card', page).forEach(function(c){ var inp=qs('input',c); c.classList.toggle('is-selected', !!(inp&&inp.checked)); }); }
      r.addEventListener('change', sync); sync();
    });
    var note=qs('textarea[name="thank_you_text"]', page), notePreview=qs('.fq-invoice-foot p', page), thermalNote=qsa('.fq-thermal-paper p', page).pop(), badgeText=qs('.fq-round-badge span', page);
    if(note){ note.addEventListener('input', function(){ if(notePreview) notePreview.textContent=note.value; if(thermalNote) thermalNote.textContent=note.value; if(badgeText) badgeText.innerHTML=(note.value||'Thank you! Visit again.').replace(/\n/g,'<br>'); }); }
    var color=qs('input[name="bill_brand_color"]', page), colorText=qs('[data-fq-color-text]', page);
    function applyColor(v){ if(!v) return; page.style.setProperty('--fq-bill-accent', v); if(color) color.value=v; if(colorText) colorText.value=v; }
    if(color) color.addEventListener('input', function(){applyColor(color.value)});
    if(colorText) colorText.addEventListener('input', function(){applyColor(colorText.value)});
    qsa('[data-fq-color]', page).forEach(function(b){ b.addEventListener('click', function(){ applyColor(b.getAttribute('data-fq-color')); }); });
    qsa('.fq-toggle-row input[type="checkbox"]', page).forEach(function(cb){
      cb.addEventListener('change', function(){
        var name=cb.name;
        if(name==='show_thank_you_note'){ qsa('.fq-invoice-foot p,.fq-thermal-paper p,.fq-round-badge span', page).forEach(function(el){el.style.display=cb.checked?'':'none'}); }
        if(name==='show_qr_barcode'){ var qr=qs('.fq-fake-qr', page); if(qr) qr.style.display=cb.checked?'':'none'; }
      });
    });
  });
})();


// v161 Bill Branding final functional fixes: upload save, remove flags, preview, print, disabled links.
(function(){
  function qs(s,c){return (c||document).querySelector(s)}
  function qsa(s,c){return Array.prototype.slice.call((c||document).querySelectorAll(s))}
  function setHTML(el, html){ if(el) el.innerHTML = html; }
  function printOnly(el, title){
    if(!el){ window.print(); return; }
    var w=window.open('', 'fq_bill_branding_print', 'width=520,height=780');
    if(!w){ window.print(); return; }
    w.document.open();
    w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+ (title||'Bill Preview') +'</title><style>body{margin:0;padding:18px;background:#fff;color:#111;font-family:Arial,sans-serif}img{max-width:100%;height:auto}.fq-a4-preview{max-width:760px;margin:0 auto}.fq-thermal-paper{width:300px;margin:0 auto}.fq-round-badge{width:260px;height:260px;border:2px solid #d99021;border-radius:50%;display:grid;place-items:center;text-align:center;margin:0 auto}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:5px;text-align:left}.fq-fake-qr{border:1px solid #111;width:72px;height:72px;display:grid;place-items:center}.fq-bb-btn,.no-print,button{display:none!important}</style></head><body>'+el.outerHTML+'</body></html>');
    w.document.close();
    setTimeout(function(){ w.focus(); w.print(); }, 300);
  }
  document.addEventListener('DOMContentLoaded', function(){
    var page=qs('.fq-bill-branding-page'); if(!page) return;
    var form=qs('#fqBillBrandingForm');
    if(form){
      form.addEventListener('submit', function(){
        var btn=qs('.fq-bb-btn-primary', page);
        if(btn){ btn.classList.add('is-saving'); btn.setAttribute('disabled','disabled'); btn.dataset.oldText=btn.innerHTML; btn.innerHTML='Saving Settings...'; }
      }, true);
    }
    qsa('[data-fq-logo-file]', page).forEach(function(input){
      input.addEventListener('change', function(){
        var key=input.getAttribute('data-fq-logo-file');
        var file=input.files && input.files[0]; if(!file) return;
        if(!/^image\//.test(file.type)){ alert('Please select a valid image file.'); input.value=''; return; }
        var url=URL.createObjectURL(file);
        var preview=qs('[data-fq-logo-preview="'+key+'"]', page);
        setHTML(preview, '<img src="'+url+'" alt="Logo preview">'+(key==='header'?'<button type="button" class="fq-icon-btn" data-fq-remove-logo="header">×</button>':''));
        var remove=qs('[data-fq-remove-hidden="'+key+'"]', page); if(remove) remove.value='0';
        var a4=qs('.fq-invoice-head img', page); if(a4){ a4.src=url; } else if(key==='restaurant'){
          var head=qs('.fq-invoice-head', page); if(head){ head.insertAdjacentHTML('afterbegin','<img src="'+url+'" alt="Logo">'); }
        }
      });
    });
    page.addEventListener('click', function(e){
      var rm=e.target.closest('[data-fq-remove-logo]');
      if(rm){
        e.preventDefault();
        var key=rm.getAttribute('data-fq-remove-logo');
        var h=qs('[data-fq-logo-hidden="'+key+'"]', page); if(h) h.value='';
        var flag=qs('[data-fq-remove-hidden="'+key+'"]', page); if(flag) flag.value='1';
        setHTML(qs('[data-fq-logo-preview="'+key+'"]', page), '<strong>No logo selected</strong>');
        if(key==='restaurant'){ var img=qs('.fq-invoice-head img', page); if(img) img.remove(); }
      }
      var disabled=e.target.closest('a.is-disabled');
      if(disabled){ e.preventDefault(); alert('No bill found yet. Create one completed order/bill first, then this button will work.'); }
      var preview=e.target.closest('[data-fq-preview-all]');
      if(preview){ e.preventDefault(); qsa('.fq-bb-preview-card', page).forEach(function(c){c.classList.add('is-pulse'); setTimeout(function(){c.classList.remove('is-pulse')}, 650);}); var p=qs('.fq-bb-preview-panel', page); if(p) p.scrollIntoView({behavior:'smooth',block:'start'}); }
      var test=e.target.closest('[data-fq-test-print]'); if(test){ e.preventDefault(); printOnly(qs('#fqThermalBillPreview', page), 'Thermal Bill Preview'); }
      var customize=e.target.closest('[data-fq-customize-badge]'); if(customize){ e.preventDefault(); var span=qs('.fq-round-badge span', page); var current=span ? span.innerText : 'Thank you!\nVisit again.'; var val=prompt('Customize badge text', current); if(val!==null && span){ span.innerHTML=val.replace(/\n/g,'<br>'); } }
    });
    var note=qs('textarea[name="thank_you_text"]', page), count=qs('.fq-bb-count', page);
    function syncNote(){ var v=(note&&note.value)||''; if(count) count.textContent=v.length+'/120'; qsa('.fq-invoice-foot p,.fq-thermal-paper p:last-child,.fq-round-badge span', page).forEach(function(el){ if(el.classList.contains('fq-round-badge')) return; el.innerHTML=v.replace(/\n/g,'<br>'); }); }
    if(note){ note.addEventListener('input', syncNote); syncNote(); }
    var color=qs('input[name="bill_brand_color"]', page), colorText=qs('[data-fq-color-text]', page);
    function applyColor(v){ if(!v) return; page.style.setProperty('--fq-bill-accent', v); if(color) color.value=v; if(colorText) colorText.value=v; }
    if(color) color.addEventListener('input', function(){ applyColor(color.value); });
    if(colorText) colorText.addEventListener('input', function(){ applyColor(colorText.value); });
    qsa('[data-fq-color]', page).forEach(function(b){ b.addEventListener('click', function(){ applyColor(b.getAttribute('data-fq-color')); }); });
    qsa('.fq-paper-card input[type="radio"]', page).forEach(function(r){
      function sync(){ qsa('.fq-paper-card', page).forEach(function(card){ var inp=qs('input',card); card.classList.toggle('is-selected', !!(inp&&inp.checked)); }); }
      r.addEventListener('change', sync); sync();
    });
    qsa('.fq-toggle-row input[type="checkbox"]', page).forEach(function(cb){
      cb.addEventListener('change', function(){
        if(cb.name==='show_qr_barcode'){ qsa('.fq-fake-qr', page).forEach(function(q){q.style.display=cb.checked?'':'none';}); }
        if(cb.name==='show_thank_you_note'){ qsa('.fq-invoice-foot p,.fq-thermal-paper p:last-child,.fq-round-badge span', page).forEach(function(el){el.style.display=cb.checked?'':'none';}); }
        if(cb.name==='show_gst_number'){ qsa('.fq-invoice-head p', page).forEach(function(p){ if(/GSTIN/i.test(p.innerHTML)) p.style.display=cb.checked?'':'none'; }); }
      });
    });
  });
})();

