// v170 Add Item editor fix: open the existing item form reliably without changing backend workflow.
document.addEventListener('DOMContentLoaded', function () {
  var page = document.querySelector('.fq-menu-exact-v169');
  if (!page) return;
  var editor = page.querySelector('#fqMenuEditor');
  if (!editor) return;

  function openMenuEditor(resetForNew) {
    editor.classList.add('is-open');
    if (resetForNew) {
      var title = editor.querySelector('.fq-panel-head h3');
      if (title) title.textContent = 'Add Item';
      var form = editor.querySelector('form');
      if (form) {
        form.reset();
        var itemId = form.querySelector('input[name="item_id"]');
        if (itemId) itemId.value = '0';
        var available = form.querySelector('input[name="is_available"]');
        if (available) available.checked = true;
        var featured = form.querySelector('input[name="is_featured"]');
        if (featured) featured.checked = false;
        var saveBtn = form.querySelector('.fq-menu-save-btn');
        if (saveBtn) saveBtn.textContent = 'Save Item';
        var emoji = form.querySelector('input[name="emoji"]');
        if (emoji && !emoji.value) emoji.value = '🍽️';
      }
    }
    window.setTimeout(function () {
      editor.scrollIntoView({ behavior: 'smooth', block: 'start' });
      var first = editor.querySelector('input[name="name"]');
      if (first) first.focus({ preventScroll: true });
    }, 80);
  }

  page.querySelectorAll('[data-fq-open-menu-editor], a[href="#fqMenuEditor"]').forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      openMenuEditor(true);
      if (history && history.replaceState) {
        history.replaceState(null, '', '#fqMenuEditor');
      }
    });
  });

  page.querySelectorAll('[data-fq-close-menu-editor]').forEach(function (link) {
    link.addEventListener('click', function (e) {
      if (editor.classList.contains('is-open') && !editor.classList.contains('is-editing')) {
        e.preventDefault();
        editor.classList.remove('is-open');
        if (history && history.replaceState) history.replaceState(null, '', window.location.pathname + window.location.search.replace(/([?&])add_item=1(&)?/, '$1').replace(/[?&]$/, ''));
      }
    });
  });

  if (window.location.hash === '#fqMenuEditor' || new URLSearchParams(window.location.search).get('add_item') === '1') {
    openMenuEditor(!editor.classList.contains('is-open'));
  }
});


// v171 reviews management UI interactions.
document.addEventListener('DOMContentLoaded', function(){
  var page = document.querySelector('.fq-reviews-exact-v171');
  if(!page) return;
  var panel = page.querySelector('[data-fq-review-details]');
  function setText(sel, txt){ var el=panel && panel.querySelector(sel); if(el) el.textContent = txt || '—'; }
  function updatePanel(data){
    if(!panel || !data) return;
    setText('[data-rv-customer]', data.customer);
    setText('[data-rv-phone]', data.phone || 'No phone');
    setText('[data-rv-source]', data.source);
    setText('[data-rv-order]', data.order_ref);
    setText('[data-rv-item]', data.item);
    setText('[data-rv-place-label]', data.place_label);
    setText('[data-rv-place]', data.place_value);
    setText('[data-rv-date]', new Date((data.date||'').replace(' ','T')).toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'}));
    setText('[data-rv-rating]', Number(data.rating||0).toFixed(1));
    setText('[data-rv-stars]', '★'.repeat(Number(data.rating||0)) + '☆'.repeat(5-Number(data.rating||0)));
    setText('[data-rv-status]', String(data.status||'published').replace(/_/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();}));
    setText('[data-rv-summary]', data.summary);
    var idInput = panel.querySelector('[data-rv-id-input]'); if(idInput) idInput.value = data.id || '';
    var reply = panel.querySelector('[data-rv-reply]'); if(reply) reply.value = data.reply || 'Thank you for your valuable feedback. We are glad to serve you.';
    var contact = panel.querySelector('[data-rv-contact]'); if(contact) contact.href = data.phone ? 'https://wa.me/' + String(data.phone).replace(/\D+/g,'') : '#';
    var wa = panel.querySelector('[data-rv-wa]'); if(wa) wa.href = data.phone ? 'https://wa.me/' + String(data.phone).replace(/\D+/g,'') : '#';
    var call = panel.querySelector('[data-rv-call]'); if(call) call.href = data.phone ? 'tel:' + data.phone : '#';
  }
  page.querySelectorAll('.fq-rv-row').forEach(function(row){
    row.addEventListener('click', function(e){
      if(e.target.closest('a,button,input,textarea,select')) return;
      page.querySelectorAll('.fq-rv-row').forEach(function(r){r.classList.remove('is-selected');});
      row.classList.add('is-selected');
      try { updatePanel(JSON.parse(row.getAttribute('data-review')||'{}')); } catch(err) {}
    });
    row.querySelectorAll('[data-fq-review-select]').forEach(function(btn){ btn.addEventListener('click', function(e){ e.stopPropagation(); row.click(); }); });
  });
  page.querySelectorAll('[data-rv-submit-action]').forEach(function(btn){
    btn.addEventListener('click', function(){ var input=page.querySelector('[data-rv-action-input]'); if(input) input.value = btn.getAttribute('data-rv-submit-action') || 'reply'; });
  });
  var open = page.querySelector('[data-fq-request-review]');
  var modal = page.querySelector('[data-fq-review-modal]');
  var close = page.querySelector('[data-fq-review-modal-close]');
  if(open && modal) open.addEventListener('click', function(){ modal.hidden=false; });
  if(close && modal) close.addEventListener('click', function(){ modal.hidden=true; });
  if(modal) modal.addEventListener('click', function(e){ if(e.target===modal) modal.hidden=true; });
});


