(function(){
  function initSubscriptionPlanSlider(){
    var track = document.querySelector('.fq-plan-cards-v174');
    if(!track) return;
    if(track.dataset.fqSliderInit === '1') return;
    track.dataset.fqSliderInit = '1';
    track.addEventListener('wheel', function(e){
      if(window.innerWidth > 1100) return;
      if(Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
      e.preventDefault();
      track.scrollBy({left: e.deltaY, behavior: 'smooth'});
    }, {passive:false});
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', initSubscriptionPlanSlider);
  }else{
    initSubscriptionPlanSlider();
  }
})();



/* v176 Subscription plan comparison slider controls */
(function(){
  function initFqxPlanSliderV176(){
    var shell = document.querySelector('[data-fq-plan-slider]');
    if(!shell || shell.dataset.fqV176Ready === '1') return;
    shell.dataset.fqV176Ready = '1';
    var track = shell.querySelector('.fq-plan-cards-v174');
    var prev = shell.querySelector('.fq-plan-slider-btn-v176.prev');
    var next = shell.querySelector('.fq-plan-slider-btn-v176.next');
    var dotsWrap = shell.querySelector('.fq-plan-slider-dots-v176');
    if(!track) return;

    var cards = Array.prototype.slice.call(track.querySelectorAll('.fq-plan-card-v174'));
    if(dotsWrap && !dotsWrap.children.length){
      cards.forEach(function(_, i){
        var dot = document.createElement('span');
        if(i === 0) dot.className = 'is-active';
        dotsWrap.appendChild(dot);
      });
    }
    var dots = dotsWrap ? Array.prototype.slice.call(dotsWrap.children) : [];
    function cardStep(){
      var card = track.querySelector('.fq-plan-card-v174');
      if(!card) return Math.max(280, track.clientWidth * 0.8);
      var gap = parseFloat(getComputedStyle(track).gap || '16') || 16;
      return card.getBoundingClientRect().width + gap;
    }
    function updateDots(){
      if(!dots.length) return;
      var idx = Math.round(track.scrollLeft / Math.max(1, cardStep()));
      dots.forEach(function(dot, i){ dot.classList.toggle('is-active', i === idx); });
    }
    if(prev) prev.addEventListener('click', function(){ track.scrollBy({left:-cardStep(), behavior:'smooth'}); });
    if(next) next.addEventListener('click', function(){ track.scrollBy({left:cardStep(), behavior:'smooth'}); });
    dots.forEach(function(dot, i){
      dot.addEventListener('click', function(){ track.scrollTo({left:i * cardStep(), behavior:'smooth'}); });
    });
    track.addEventListener('scroll', function(){ window.requestAnimationFrame(updateDots); }, {passive:true});
    track.addEventListener('wheel', function(e){
      if(Math.abs(e.deltaY) > Math.abs(e.deltaX)){
        e.preventDefault();
        track.scrollBy({left:e.deltaY, behavior:'smooth'});
      }
    }, {passive:false});
    var current = track.querySelector('.fq-plan-card-v174.is-current');
    if(current){
      setTimeout(function(){
        track.scrollTo({left: Math.max(0, current.offsetLeft - 24), behavior:'smooth'});
        updateDots();
      }, 300);
    }
    updateDots();
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initFqxPlanSliderV176);
  else initFqxPlanSliderV176();
})();

// v179 Room QR Template Studio interactions
(function(){
  function ready(fn){ if(document.readyState !== 'loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  ready(function(){
    var form = document.querySelector('.fq-template-save-form');
    if(!form) return;
    var roomSelect = document.querySelector('.fq-room-template-room-select');
    var roomInput = form.querySelector('.fq-template-room-id');
    if(roomSelect && roomInput){
      roomSelect.addEventListener('change', function(){
        roomInput.value = roomSelect.value;
        var url = new URL(window.location.href);
        url.searchParams.set('section','templates');
        url.searchParams.set('room_id', roomSelect.value);
        window.location.href = url.toString();
      });
    }
    function refreshCards(){
      form.querySelectorAll('.fq-template-card').forEach(function(card){
        var radio = card.querySelector('.fq-template-radio');
        var badge = card.querySelector('.fq-template-badge');
        var active = !!(radio && radio.checked);
        card.classList.toggle('is-selected', active);
        card.classList.toggle('fq-template-selected', active);
        if(badge) badge.textContent = active ? 'Selected ✓' : 'Select';
      });
    }
    form.querySelectorAll('.fq-template-card').forEach(function(card){
      card.addEventListener('click', function(){
        var radio = card.querySelector('.fq-template-radio');
        if(radio){ radio.checked = true; radio.dispatchEvent(new Event('change', {bubbles:true})); }
      });
    });
    form.addEventListener('change', function(e){
      if(e.target && e.target.classList && e.target.classList.contains('fq-template-radio')) refreshCards();
    });
    refreshCards();

    form.addEventListener('submit', function(){
      var btn = form.querySelector('button[type="submit"]');
      if(btn){ btn.textContent = 'Saving Template...'; btn.disabled = true; }
    });
  });
})();
